package main

import (
	"bufio"
	"fmt"
	"net"
	"os"
	"strings"
)

// Storage for key-value pairs
var storage = make(map[string]string)

// Handle incoming connections and process commands
func handleConnection(conn net.Conn) {
	defer conn.Close()

	reader := bufio.NewReader(conn)
	for {
		command, err := reader.ReadString('\n')
		if err != nil {
			fmt.Println("Error reading command:", err)
			return
		}

		command = strings.TrimSpace(command)
		parts := strings.SplitN(command, " ", 3)

		switch parts[0] {
		case "SET":
			if len(parts) < 3 {
				conn.Write([]byte("ERR: SET requires a key and value\n"))
			} else {
				storage[parts[1]] = parts[2]
				conn.Write([]byte("OK\n"))
			}
		case "GET":
			if len(parts) < 2 {
				conn.Write([]byte("ERR: GET requires a key\n"))
			} else {
				value, ok := storage[parts[1]]
				if !ok {
					conn.Write([]byte("ERR: Key not found\n"))
				} else {
					conn.Write([]byte(value + "\n"))
				}
			}
		case "DELETE":
			if len(parts) < 2 {
				conn.Write([]byte("ERR: DELETE requires a key\n"))
			} else {
				delete(storage, parts[1])
				conn.Write([]byte("OK\n"))
			}
		default:
			conn.Write([]byte("ERR: Unknown command\n"))
		}
	}
}

func main() {
	port := "8080"

	listener, err := net.Listen("tcp", ":"+port)
	if err != nil {
		fmt.Println("Error starting server:", err)
		os.Exit(1)
	}
	defer listener.Close()

	fmt.Println("Server listening on port", port)

	for {
		conn, err := listener.Accept()
		if err != nil {
			fmt.Println("Error accepting connection:", err)
			continue
		}

		go handleConnection(conn)
	}
}

Here's a JavaScript function that implements the merge sort algorithm:

```javascript
function mergeSort(arr) {
  if (arr.length <= 1) {
    return arr;
  }

  const middle = Math.floor(arr.length / 2);
  const left = arr.slice(0, middle);
  const right = arr.slice(middle);

  return merge(mergeSort(left), mergeSort(right));
}

function merge(left, right) {
  let result = [];
  let indexLeft = 0;
  let indexRight = 0;

  while (indexLeft < left.length && indexRight < right.length) {
    if (left[indexLeft] < right[indexRight]) {
      result.push(left[indexLeft]);
      indexLeft++;
    } else {
      result.push(right[indexRight]);
      indexRight++;
    }
  }

  return result.concat(left.slice(indexLeft)).concat(right.slice(indexRight));
}

// Example usage:
const arr = [4, 7, 2, 9, 1, 5, 3];
console.log(mergeSort(arr)); // Output: [1, 2, 3, 4, 5, 7, 9]
```

This function first checks if the input array has a length of 1 or less. If so, it returns the array as-is since it is already sorted.

If the array has more than one element, it splits the array into two halves and recursively calls `mergeSort()` on each half. Then, it merges the sorted halves back together using the `merge()` helper function.

The `merge()` function takes in two sorted arrays (`left` and `right`) and combines them into a single sorted array. It does this by iterating through both arrays and comparing their elements at the current indices. The smaller element is added to the result array, and its corresponding index is incremented. This process continues until one of the arrays is exhausted, at which point the remaining elements from both arrays are concatenated to the result array.

