def fibonacci_memoization(limit, memo={}):
    if limit in memo:
        return memo[limit]
    elif limit <= 1:
        memo[limit] = limit
    else:
        memo[limit] = fibonacci_memoization(limit - 1) + fibonacci_memoization(limit - 2)
    return memo[limit]

def generate_fibonacci_numbers(limit):
    numbers = []
    for i in range(limit + 1):
        numbers.append(fibonacci_memoization(i))
    return numbers

