func main() {
	if len(os.Args) < 2 {
		fmt.Println("Please provide a CSV file as an argument.")
		os.Exit(1)
	}

	file, err := os.Open(os.Args[1])
	if err != nil {
		fmt.Printf("Error opening file: %v\n", err)
		os.Exit(1)
	}
	defer file.Close()

	reader := csv.NewReader(file)
	records, err := reader.ReadAll()
	if err != nil {
		fmt.Printf("Error reading CSV data: %v\n", err)
		os.Exit(1)
	}

	printTable(records)
}

func printTable(records [][]string) {
	columnWidths := getColumnWidths(records)

	for _, row := range records {
		for i, cell := range row {
			fmt.Printf("%-*s ", columnWidths[i], cell)
		}
		fmt.Println()
	}
}

func getColumnWidths(records [][]string) []int {
	widths := make([]int, len(records[0]))

	for _, row := range records {
		for i, cell := range row {
			cellLength := len(strings.TrimSpace(cell))
			if widths[i] < cellLength {
				widths[i] = cellLength
			}
		}
	}

	return widths
}

