import (
	"fmt"
)

// longestIncreasingSubsequence finds the longest increasing subsequence in an array of integers
func longestIncreasingSubsequence(arr []int) []int {
	n := len(arr)
	if n == 0 {
		return arr
	}

	dp := make([]int, n)
	for i := range dp {
		dp[i] = 1
	}
	maxIndex := 0

	for i := 1; i < n; i++ {
		for j := 0; j < i; j++ {
			if arr[i] > arr[j] && dp[i] < dp[j]+1 {
				dp[i] = dp[j] + 1
				if dp[maxIndex] < dp[i] {
					maxIndex = i
				}
			}
		}
	}

	result := make([]int, dp[maxIndex])
	i := maxIndex
	j := dp[maxIndex] - 1
	result[j] = arr[i]
	j--

	for i--; i >= 0; i-- {
		if arr[i] < result[j+1] && dp[i] == dp[maxIndex]-1 {
			result[j] = arr[i]
			j--
			maxIndex = i
		}
	}

	return result
}

