	fmt.Scan(&length)

	fmt.Print("Include uppercase letters? (y/n): ")
	includeUppercase = askYesNo()

	fmt.Print("Include digits? (y/n): ")
	includeDigits = askYesNo()

	fmt.Print("Include special characters? (y/n): ")
	includeSpecial = askYesNo()

	password := generatePassword(length, includeUppercase, includeDigits, includeSpecial)
	fmt.Println("Generated password:", password)
}

func askYesNo() bool {
	var input string
	for {
		fmt.Scan(&input)
		if input == "y" || input == "Y" {
			return true
		} else if input == "n" || input == "N" {
			return false
		} else {
			fmt.Print("Invalid input. Please enter 'y' or 'n': ")
		}
	}
}

func generatePassword(length int, includeUppercase, includeDigits, includeSpecial bool) string {
	charSet := lowercaseLetters
	if includeUppercase {
		charSet += uppercaseLetters
	}
	if includeDigits {
		charSet += digits
	}
	if includeSpecial {
		charSet += specialChars
	}

	password := make([]byte, length)
	for i := 0; i < length; i++ {
		randomIndex, _ := rand.Int(rand.Reader, big.NewInt(int64(len(charSet))))
		password[i] = charSet[randomIndex.Int64()]
	}

	return string(password)
}

