Here is a simple implementation of stack using linked list in C:

```c
#include <stdio.h>
#include <stdlib.h>

// Define structure for stack node
struct Node {
    int data;
    struct Node* next;
};

// Function to create a new node with given data 
struct Node* newNode(int data) {
    struct Node* stackNode = (struct Node*) malloc(sizeof(struct Node));
    stackNode->data = data;
    stackNode->next = NULL;
    return stackNode;
}

// Function to check if the stack is empty
int isEmpty(struct Node *root) {
    return !root;
}

// Function to push an item to stack
void push(struct Node** root, int data) {
    struct Node* stackNode = newNode(data);
    stackNode->next = *root;
    *root = stackNode;
    printf("%d pushed to stack\n", data);
}

// Function to pop an item from stack
int pop(struct Node** root) {
    if (isEmpty(*root))
        return INT_MIN;
    struct Node* temp = *root;
    *root = (*root)->next;
    int popped = temp->data;
    free(temp);

    return popped;
}

// Function to return the top from stack without removing it
int peek(struct Node* root) {
    if (isEmpty(root))
        return INT_MIN;
    return root->data;
}

// Driver program to test above functions
int main() {
    struct Node* root = NULL;

    push(&root, 10);
    push(&root, 20);
    push(&root, 30);

    printf("Popped from stack: %d\n", pop(&root));

    printf("Top element is %d\n", peek(root));

    return 0;
}
```

This program creates a Stack data structure using Linked List. It has functions `push` to add elements on top of the stack, `pop` to remove elements from top of the stack, `peek` to get the topmost element of the stack and `isEmpty` to check whether the stack is empty or not. The `main` function demonstrates these operations.

