#include <opencv2/opencv.hpp>

int main() {
    // Open the default camera
    cv::VideoCapture cap(0);
    if (!cap.isOpened()) {
        std::cerr << "ERROR: Unable to open the camera" << std::endl;
        return 1;
    }

    // Get the width and height of the camera stream
    int frame_width = static_cast<int>(cap.get(cv::CAP_PROP_FRAME_WIDTH));
    int frame_height = static_cast<int>(cap.get(cv::CAP_PROP_FRAME_HEIGHT));

    // Create a VideoWriter object to save the output video
    cv::VideoWriter out("output.avi", cv::VideoWriter::fourcc('M', 'J', 'P', 'G'), 30, cv::Size(frame_width, frame_height), false);

    // Check if the VideoWriter is opened successfully
    if (!out.isOpened()) {
        std::cerr << "ERROR: Unable to open the output video file" << std::endl;
        return 1;
    }

    cv::Mat frame, gray_frame;

    while (true) {
        // Capture a new frame from the camera
        cap >> frame;
        if (frame.empty()) {
            std::cerr << "ERROR: Unable to capture frame" << std::endl;
            break;
        }

        // Convert the frame to grayscale
        cv::cvtColor(frame, gray_frame, cv::COLOR_BGR2GRAY);

        // Write the processed frame to the output video file
        out.write(gray_frame);

        // Display the original and processed frames
        cv::imshow("Original Frame", frame);
        cv::imshow("Grayscale Frame", gray_frame);

        // Exit the loop if 'q' is pressed
        if (cv::waitKey(1) == 'q') {
            break;
        }
    }

    // Release resources
    cap.release();
    out.release();
    cv::destroyAllWindows();

    return 0;
}

