function quickSort(arr, left = 0, right = arr.length - 1) {
    if (left < right) {
        const pivotIndex = partition(arr, left, right);

        // Recursively sort elements on the left and right sides of the pivot
        quickSort(arr, left, pivotIndex - 1);
        quickSort(arr, pivotIndex + 1, right);
    }
    return arr;
}

function partition(arr, left, right) {
    const pivot = arr[right];
    let i = left;

    for (let j = left; j < right; j++) {
        if (arr[j] <= pivot) {
            [arr[i], arr[j]] = [arr[j], arr[i]];
            i++;
        }
    }

    // Swap the pivot element with the element at index i
    [arr[i], arr[right]] = [arr[right], arr[i]];

    return i;
}

import scala.collection.mutable

case class Edge(to: Int, weight: Int)

object Dijkstra {
  def shortestPath(graph: Map[Int, List[Edge]], start: Int, end: Int): Option[List[Int]] = {
    val unvisitedNodes = mutable.Set.from(graph.keys)
    val distances = mutable.Map(start -> 0)
    val previousNodes = mutable.Map.empty[Int, Int]

    while (unvisitedNodes.nonEmpty) {
      val currentNode = unvisitedNodes.minBy(node => distances.getOrElse(node, Int.MaxValue))
      if (currentNode == end) return Some(reconstructPath(previousNodes, start, end))

      unvisitedNodes -= currentNode

      for (edge <- graph(currentNode)) {
        val newDistance = distances(currentNode) + edge.weight
        if (!distances.contains(edge.to) || newDistance < distances(edge.to)) {
          distances(edge.to) = newDistance
          previousNodes(edge.to) = currentNode
        }
      }
    }

    None
  }

  private def reconstructPath(previousNodes: mutable.Map[Int, Int], start: Int, end: Int): List[Int] = {
    val path = mutable.ListBuffer(end)
    var currentNode = end

    while (currentNode != start) {
      currentNode = previousNodes(currentNode)
      path.prepend(currentNode)
    }

    path.toList
  }
}

def main(args: Array[String]): Unit = {
  val graph = Map(
    1 -> List(Edge(2, 7), Edge(3, 9), Edge(6, 14)),
    2 -> List(Edge(1, 7), Edge(3, 10), Edge(4, 15)),
    3 -> List(Edge(1, 9), Edge(2, 10), Edge(4, 11), Edge(6, 2)),
    4 -> List(Edge(2, 15), Edge(3, 11), Edge(5, 6)),
    5 -> List(Edge(4, 6), Edge(6, 9)),
    6 -> List(Edge(1, 14), Edge(3, 2), Edge(5, 9))
  )

  val start = 1
  val end = 5

  Dijkstra.shortestPath(graph, start, end) match {
    case Some(path) => println(s"Shortest path from $start to $end: ${path.mkString(" -> ")}")
    case None => println(s"No path found between $start and $end.")
  }
}

