// Function to merge two sorted lists into one sorted list
function mergeSortedLists(list1, list2) {
    // Create an empty array to store the merged list
    var mergedList = [];

    // While both lists have elements left in them
    while (list1.length && list2.length) {
        // If the first element of list1 is less than the first element of list2
        if (list1[0] < list2[0]) {
            // Remove the first element from list1 and push it to the merged list
            mergedList.push(list1.shift());
        } else {
            // Otherwise, remove the first element from list2 and push it to the merged list
            mergedList.push(list2.shift());
        }
    }

    // If there are any remaining elements in either list, concatenate them to the merged list
    return mergedList.concat(list1.slice()).concat(list2.slice());
}

public class FibonacciDynamicProgramming {

    public static void main(String[] args) {
        int n = 10; // Change this value to compute the nth Fibonacci number

        System.out.println("Fibonacci number at position " + n + " is: " + fibonacci(n));
    }

    private static long fibonacci(int n) {
        if (n <= 1) {
            return n;
        }

        long[] fib = new long[n + 1];
        fib[0] = 0;
        fib[1] = 1;

        for (int i = 2; i <= n; i++) {
            fib[i] = fib[i - 1] + fib[i - 2];
        }

        return fib[n];
    }
}

