// Function to find the largest and smallest number in an array
function findLargestAndSmallest(arr) {
    // Initialize largest and smallest with first element of the array
    let largest = arr[0];
    let smallest = arr[0];

    // Loop through the array
    for(let i = 1; i < arr.length; i++) {
        // If current element is greater than largest, update largest
        if(arr[i] > largest) {
            largest = arr[i];
        }

        // If current element is smaller than smallest, update smallest
        if(arr[i] < smallest) {
            smallest = arr[i];
        }
    }

    // Return the largest and smallest numbers
    return {largest: largest, smallest: smallest};
}

class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def add_element(self, data):
        new_node = Node(data)
        if not self.head:
            self.head = new_node
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = new_node

    def remove_element(self, value):
        if not self.head:
            return
        if self.head.data == value:
            self.head = self.head.next
            return
        current = self.head
        while current.next:
            if current.next.data == value:
                current.next = current.next.next
                return
            current = current.next

    def print_list(self):
        current = self.head
        while current:
            print(current.data, end=" -> ")
            current = current.next
        print("None")

