// Function to calculate factorial using recursion
function factorial(n) {
    // Check if input is a positive integer
    if (n < 0 || !Number.isInteger(n)) {
        throw new Error('Input must be a positive integer');
    }

    // Base case: factorial of 0 or 1 is 1
    if (n === 0 || n === 1) {
        return 1;
    } else {
        // Recursive case: n * factorial of (n - 1)
        return n * factorial(n - 1);
    }
}

#include <iostream>
#include <vector>
#include <thread>
#include <mutex>

std::mutex mtx;

// Function to calculate the dot product of two vectors in a given range
void dot_product(const std::vector<int>& v1, const std::vector<int>& v2, int& result, int start, int end) {
    int partial_sum = 0;
    for (int i = start; i < end; ++i) {
        partial_sum += v1[i] * v2[i];
    }

    // Lock the mutex to protect access to shared variable 'result'
    std::unique_lock<std::mutex> lock(mtx);
    result += partial_sum;
    lock.unlock();
}

int main() {
    int size = 1000000;
    std::vector<int> v1(size, 1), v2(size, 2);

    int num_threads = std::thread::hardware_concurrency();
    std::vector<std::thread> threads(num_threads);
    int result = 0;

    // Divide work among multiple threads
    int chunk_size = size / num_threads;
    for (int i = 0; i < num_threads; ++i) {
        int start = i * chunk_size;
        int end = (i == num_threads - 1) ? size : start + chunk_size;
        threads[i] = std::thread(dot_product, std::ref(v1), std::ref(v2), std::ref(result), start, end);
    }

    // Join all threads and print the final result
    for (auto& t : threads) {
        t.join();
    }

    std::cout << "Dot product: " << result << std::endl;

    return 0;
}

