func main() {
	if len(os.Args) < 2 {
		fmt.Println("Please provide a path to the log file(s)")
		os.Exit(1)
	}

	path := os.Args[1]
	files, err := filepath.Glob(path + "/*.log")
	if err != nil {
		panic(err)
	}

	wordCounts := make(map[string]int)
	var mutex sync.Mutex
	var wg sync.WaitGroup

	for _, file := range files {
		wg.Add(1)
		go func(file string) {
			defer wg.Done()
			processFile(file, &mutex, wordCounts)
		}(file)
	}

	wg.Wait()

	topWords := getTopWords(wordCounts, 10)
	for i, wc := range topWords {
		fmt.Printf("%d. %s: %d\n", i+1, wc.Word, wc.Count)
	}
}

func processFile(file string, mutex *sync.Mutex, wordCounts map[string]int) {
	f, err := os.Open(file)
	if err != nil {
		panic(err)
	}
	defer f.Close()

	scanner := bufio.NewScanner(f)
	scanner.Split(bufio.ScanWords)

	for scanner.Scan() {
		word := strings.ToLower(scanner.Text())
		mutex.Lock()
		wordCounts[word]++
		mutex.Unlock()
	}
}

func getTopWords(wordCounts map[string]int, n int) []WordCount {
	wordList := make([]WordCount, 0, len(wordCounts))
	for word, count := range wordCounts {
		wordList = append(wordList, WordCount{word, count})
	}

	sort.Slice(wordList, func(i, j int) bool {
		return wordList[i].Count > wordList[j].Count
	})

	if n > len(wordList) {
		n = len(wordList)
	}
	return wordList[:n]
}

